"""Complete SQL-text adapter for the offline synthetic order dataset."""

_ORDER_COLUMNS = "order_id, tenant_id, customer, amount, status"


def _sql_literal(value):
    """Encode a string as a SQLite literal by doubling embedded single quotes."""
    if not isinstance(value, str):
        raise TypeError("string argument required, got {0}".format(type(value).__name__))
    return "'" + value.replace("'", "''") + "'"


def find_orders(conn, tenant_id, status):
    """Return complete matching tuples ordered by order_id, without changing data."""
    sql = (
        "SELECT " + _ORDER_COLUMNS + " FROM orders"
        " WHERE tenant_id = " + _sql_literal(tenant_id)
        + " AND status = " + _sql_literal(status)
        + " ORDER BY order_id"
    )
    return conn.execute(sql).fetchall()
EOF
